/bin/bash -lc "env PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import ast
import json
import pathlib

path = pathlib.Path(\"controlled_content_generator_v2_001/gate1_v1_1_001/p7_successor_longrun_001/delivery_control_001/tests/test_negative_attacks.py\")
tree = ast.parse(path.read_text(encoding=\"utf-8\"))
rows = []
for node in ast.walk(tree):
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith(\"test_attack_\"):
        assert_calls = []
        skip_decorators = []
        bare_pass = 0
        for sub in ast.walk(node):
            if isinstance(sub, ast.Call):
                func = sub.func
                name = func.attr if isinstance(func, ast.Attribute) else func.id if isinstance(func, ast.Name) else \"\"
                if name.startswith(\"assert\"):
                    assert_calls.append(name)
            if isinstance(sub, ast.Pass):
                bare_pass += 1
        for dec in node.decorator_list:
            skip_decorators.append(ast.unparse(dec))
        rows.append({
            \"name\": node.name,
            \"assert_calls\": sorted(assert_calls),
            \"assert_call_count\": len(assert_calls),
            \"decorators\": skip_decorators,
            \"bare_pass_count\": bare_pass,
        })
print(json.dumps({
    \"attack_test_count\": len(rows),
    \"tests_without_assert_calls\": [r[\"name\"] for r in rows if r[\"assert_call_count\"] == 0],
    \"tests_with_skip_decorators\": [r for r in rows if any(\"skip\" in d.lower() for d in r[\"decorators\"])],
    \"tests_with_bare_pass\": [r[\"name\"] for r in rows if r[\"bare_pass_count\"]],
    \"selected\": [r for r in rows if r[\"name\"] in {
        \"test_attack_04_forged_typed_status\",
        \"test_attack_15_b_track_depends_on_s1_pass_again\",
        \"test_attack_19_actual_state_rewritten_to_expectation\",
        \"test_attack_29_launcher_subagent_impersonates_session\",
        \"test_attack_30_numbered_serialism_ignores_y_graph\",
    }],
}, ensure_ascii=False, sort_keys=True))
PY"

