import json
from pathlib import Path

base = Path(\"controlled_content_generator_v2_001/gate1_v1_1_001/p7_successor_longrun_001\")
stage = json.loads((base / \"eval_audit_spine_001/contract/stage_and_kill.v2.json\").read_text())
dag = json.loads((base / \"delivery_control_001/MILESTONE_DAG.v1.json\").read_text())
b_requirements = {
    row[\"stage_id\"]: row[\"entry_requires\"]
    for row in stage[\"stages\"] if row.get(\"track\") == \"B\"
}
forbidden = (\"S1_PASS\", \"M0_STATUS_QUALIFIED\", \"A2\")
b_offenders = {
    stage_id: [req for req in requires if any(token in req for token in forbidden)]
    for stage_id, requires in b_requirements.items()
}
b_offenders = {k: v for k, v in b_offenders.items() if v}
m6_edge = next(edge for edge in dag[\"edges\"] if edge[\"to\"] == \"M6\")
route_a_a_dependencies = [
    req for req in m6_edge[\"requires\"] + m6_edge[\"route_conditional\"][\"a\"]
    if req.get(\"milestone\") in {\"M3\", \"M4\"} or \"A2\" in req.get(\"flag\", \"\")
]
out = {
    \"b_stage_count\": len(b_requirements),
    \"b_stage_A_or_S1_dependency_offenders\": b_offenders,
    \"M6_route_a_A_track_dependencies\": route_a_a_dependencies,
}
print(json.dumps(out, sort_keys=True))
raise SystemExit(0 if len(b_requirements) == 6 and not b_offenders and not route_a_a_dependencies else 1)
PY"

